                    "name": data.get("name", agent_md_path.stem),
                    "description": data.get("description", ""),
                    "model": data.get("model", ""),
                    "mode": data.get("mode", ""),
                    "tools": data.get("tools", []),
                    "path": str(agent_md_path)
                }
