"""Checador de manifesto de dependências por skill (auditoria Claude Skills).

Para cada skill catalogada com campo `dependencies` (frontmatter SKILL.md),
verifica se os binários/libs existem no host e reporta os faltantes.
Uso pelo orquestrador (Fase 4) antes de rodar skill helenizada.
"""

from __future__ import annotations

from typing import Any, Dict, List, Tuple
import json
import shutil
from pathlib import Path

BIN_MAP: Dict[str, str] = {
    "soffice": "soffice",
    "libreoffice": "soffice",
    "poppler-utils": "pdftoppm",
    "pdftoppm": "pdftoppm",
    "gcc": "gcc",
    "git": "git",
    "python3": "python3",
    "node": "node",
    "claude": "claude",
    "opencode": "opencode",
}


def _check_dep(dep: str) -> Tuple[str, bool]:
    """Resolve dep para binário real e verifica presença no PATH."""
    binary = BIN_MAP.get(dep.strip().lower(), dep.strip().lower())
    found = shutil.which(binary) is not None
    return dep.strip(), found


def check_manifest(registry: Dict[str, Any]) -> Dict[str, Any]:
    """Analisa skills com dependencies e retorna {missing, ok}."""
    missing: Dict[str, List[str]] = {}
    ok: Dict[str, List[str]] = {}
    for skill in registry.get("skills", []):
        deps = skill.get("dependencies") or []
        if not deps:
            continue
        name = skill.get("name", "?")
        miss = []
        have = []
        for dep in deps:
            dep_name, found = _check_dep(dep)
            (have if found else miss).append(dep_name)
        if miss:
            missing[name] = miss
        if have:
            ok[name] = have
    return {"missing": missing, "ok": ok, "skills_with_manifest": len(ok) + len(missing)}


def manifest_report(registry_path: str = "/mnt/dados/harness/registry.json") -> str:
    """Gera relatório legível do manifesto de dependências."""
    try:
        with open(registry_path) as f:
            registry = json.load(f)
    except Exception as e:
        return f"manifesto indisponível: {e}"
    result = check_manifest(registry)
    lines = [f"[Manifest] skills com manifest: {result['skills_with_manifest']}"]
    if result["missing"]:
        lines.append("[Manifest] MISSING (não podem rodar no host):")
        for name, deps in sorted(result["missing"].items()):
            lines.append(f"  - {name}: falta {' '.join(deps)}")
    for name, deps in sorted(result["ok"].items()):
        lines.append(f"  ✓ {name}: {' '.join(deps)}")
    return "\n".join(lines)

