const SECRET_PATTERNS = [
  /(?:api[_-]?key|apikey)\s*[=:]\s*['"]?([^\s'"<>]{8,})/gi,
  /(?:bearer|token)\s+[A-Za-z0-9\-._~+/]+=*/gi,
  /(?:password|passwd|pwd)\s*[=:]\s*['"]?([^\s'"<>]{4,})/gi,
  /(?:secret|secret_key)\s*[=:]\s*['"]?([^\s'"<>]{8,})/gi,
  /(?:private[_-]?key)\s*[=:]\s*['"]?([^\s'"<>]{8,})/gi,
  /(?:sk-[a-zA-Z0-9]{20,})/g,
  /(?:ghp_[a-zA-Z0-9]{36})/g,
  /(?:xoxb-[a-zA-Z0-9\-]+)/g,
]

const REDACTED = "[REDACTED]"

export function redactSecrets(text: string): string {
  let result = text
  for (const pattern of SECRET_PATTERNS) {
    result = result.replace(pattern, REDACTED)
  }
  return result
}

export function redactObject(obj: unknown): unknown {
  if (typeof obj === "string") return redactSecrets(obj)
  if (Array.isArray(obj)) return obj.map(redactObject)
  if (obj && typeof obj === "object") {
    const result: Record<string, unknown> = {}
    for (const [key, value] of Object.entries(obj)) {
      if (/key|secret|token|password|credential/i.test(key) && typeof value === "string") {
        result[key] = REDACTED
      } else {
        result[key] = redactObject(value)
      }
    }
    return result
  }
  return obj
}

