import * as vscode from "vscode"
import type {
  AgentState,
  ConnectionState,
  NormalizedAgentEvent,
  SessionState,
  ToolExecution,
  FileState,
  TodoItem,
  PermissionRequest,
  DiagnosticState,
  SerializableAgentEvent,
} from "../events/EventTypes"

type Listener = (state: AgentState) => void

const MAX_TIMELINE = 5000
const MAX_RECENT_TOOLS = 50

export class StateStore {
  private state: AgentState = {
    connection: "DISCONNECTED",
    sessions: new Map(),
    timeline: [],
    recentTools: [],
    files: new Map(),
    diffs: new Map(),
    todos: [],
    permissions: [],
    diagnostics: [],
  }
  private listeners: Set<Listener> = new Set()
  private outputChannel?: vscode.OutputChannel

  constructor(outputChannel?: vscode.OutputChannel) {
    this.outputChannel = outputChannel
  }

  getState(): AgentState {
    return this.state
  }

  subscribe(listener: Listener): () => void {
    this.listeners.add(listener)
    return () => this.listeners.delete(listener)
  }

  private notify(): void {
    for (const listener of this.listeners) {
      try {
        listener(this.state)
      } catch {
        // subscriber error — ignore
      }
    }
  }

  setConnection(connection: ConnectionState): void {
    this.state.connection = connection
    this.notify()
  }

  setServerVersion(version: string): void {
    this.state.serverVersion = version
    this.notify()
  }

  setError(error: string | undefined): void {
    this.state.error = error
    this.notify()
  }

  // Sessions
  setSessions(sessions: SessionState[]): void {
    this.state.sessions.clear()
    for (const s of sessions) {
      this.state.sessions.set(s.id, s)
    }
    this.notify()
  }

  updateSession(session: SessionState): void {
    this.state.sessions.set(session.id, session)
    if (!this.state.activeSessionId) {
      this.state.activeSessionId = session.id
    }
    this.notify()
  }

  removeSession(id: string): void {
    this.state.sessions.delete(id)
    if (this.state.activeSessionId === id) {
      this.state.activeSessionId = this.state.sessions.keys().next().value
    }
    this.notify()
  }

  setActiveSession(id: string): void {
    this.state.activeSessionId = id
    this.notify()
  }

  // Timeline
  addEvent(event: NormalizedAgentEvent): void {
    this.state.timeline.push(event)
    if (this.state.timeline.length > MAX_TIMELINE) {
      this.state.timeline = this.state.timeline.slice(-MAX_TIMELINE)
    }
    this.state.lastEventAt = event.timestamp
    this.notify()
  }

  clearTimeline(): void {
    this.state.timeline = []
    this.notify()
  }

  // Tools
  setToolRunning(tool: ToolExecution): void {
    this.state.activeTool = tool
    this.notify()
  }

  setToolFinished(toolId: string, status: "success" | "error"): void {
    if (this.state.activeTool?.id === toolId) {
      this.state.activeTool.finishedAt = Date.now()
      this.state.activeTool.status = status
      this.state.recentTools.unshift(this.state.activeTool)
      if (this.state.recentTools.length > MAX_RECENT_TOOLS) {
        this.state.recentTools = this.state.recentTools.slice(0, MAX_RECENT_TOOLS)
      }
      this.state.activeTool = undefined
    }
    this.notify()
  }

  // Files
  setFile(file: FileState): void {
    this.state.files.set(file.path, file)
    this.notify()
  }

  // Todos
  setTodos(todos: TodoItem[]): void {
    this.state.todos = todos
    this.notify()
  }

  // Permissions
  addPermission(req: PermissionRequest): void {
    this.state.permissions.unshift(req)
    this.notify()
  }

  resolvePermission(id: string, response: "allow" | "deny"): void {
    const perm = this.state.permissions.find((p) => p.id === id)
    if (perm) {
      perm.resolved = true
      perm.response = response
      perm.resolvedAt = Date.now()
    }
    this.notify()
  }

  // Diagnostics
  setDiagnostics(diagnostics: DiagnosticState[]): void {
    this.state.diagnostics = diagnostics
    this.notify()
  }

  // Serialization for webview
  toSerializable(): Record<string, unknown> {
    return {
      connection: this.state.connection,
      serverVersion: this.state.serverVersion,
      activeSessionId: this.state.activeSessionId,
      sessions: Object.fromEntries(this.state.sessions),
      timeline: this.state.timeline,
      activeTool: this.state.activeTool,
      recentTools: this.state.recentTools,
      files: Object.fromEntries(this.state.files),
      diffs: Object.fromEntries(this.state.diffs),
      todos: this.state.todos,
      permissions: this.state.permissions,
      diagnostics: this.state.diagnostics,
      lastEventAt: this.state.lastEventAt,
      error: this.state.error,
    }
  }
}

