import * as vscode from "vscode"
import { StateStore } from "../state/StateStore"
import { OpenCodeConnection } from "../opencode/OpenCodeConnection"

export function registerCommands(
  context: vscode.ExtensionContext,
  store: StateStore,
  connection: OpenCodeConnection
): void {
  context.subscriptions.push(
    vscode.commands.registerCommand("opencodeObservatory.connect", () => connection.connect()),
    vscode.commands.registerCommand("opencodeObservatory.disconnect", () => connection.disconnect()),
    vscode.commands.registerCommand("opencodeObservatory.reconnect", () => connection.reconnect()),
    vscode.commands.registerCommand("opencodeObservatory.refresh", async () => {
      const state = store.getState()
      if (state.activeSessionId) {
        store.setActiveSession(state.activeSessionId)
      }
    }),
    vscode.commands.registerCommand("opencodeObservatory.clearTimeline", () => store.clearTimeline()),
    vscode.commands.registerCommand("opencodeObservatory.selectSession", async () => {
      const state = store.getState()
      const sessions = Array.from(state.sessions.values())
      if (sessions.length === 0) {
        vscode.window.showInformationMessage("No sessions available")
        return
      }
      const picked = await vscode.window.showQuickPick(
        sessions.map((s) => ({
          label: s.title || s.id,
          description: s.model,
          detail: s.status,
          id: s.id,
        })),
        { placeHolder: "Select a session" }
      )
      if (picked) {
        await connection.selectSession(picked.id)
      }
    }),
    vscode.commands.registerCommand("opencodeObservatory.abortSession", async () => {
      const state = store.getState()
      if (state.activeSessionId) {
        const confirm = await vscode.window.showWarningMessage(
          "Abort current session?",
          "Abort",
          "Cancel"
        )
        if (confirm === "Abort") {
          await connection.abortSession(state.activeSessionId)
        }
      }
    }),
    vscode.commands.registerCommand("opencodeObservatory.openDiff", () => {
      vscode.commands.executeCommand("workbench.action.terminal.toggleTerminal")
    }),
    vscode.commands.registerCommand("opencodeObservatory.open", () => {
      vscode.commands.executeCommand("opencodeObservatory.main.focus")
    })
  )
}

