import * as vscode from "vscode"
import { StateStore } from "../state/StateStore"
import { OpenCodeConnection } from "../opencode/OpenCodeConnection"

export class ObservatoryViewProvider implements vscode.WebviewViewProvider {
  public static readonly viewType = "opencodeObservatory.main"
  private view?: vscode.WebviewView
  private disposables: vscode.Disposable[] = []

  constructor(
    private readonly extensionUri: vscode.Uri,
    private readonly store: StateStore,
    private readonly connection: OpenCodeConnection
  ) {}

  resolveWebviewView(
    webviewView: vscode.WebviewView,
    _context: vscode.WebviewViewResolveContext,
    _token: vscode.CancellationToken
  ): void {
    this.view = webviewView

    webviewView.webview.options = {
      enableScripts: true,
      localResourceRoots: [this.extensionUri],
    }

    webviewView.webview.html = this.getHtml(webviewView.webview)

    webviewView.webview.onDidReceiveMessage(
      (msg) => this.handleMessage(msg),
      undefined,
      this.disposables
    )

    this.store.subscribe(() => {
      if (this.view) {
        this.view.webview.postMessage({
          type: "state",
          state: this.store.toSerializable(),
        })
      }
    })

    if (this.view) {
      this.view.webview.postMessage({
        type: "state",
        state: this.store.toSerializable(),
      })
    }
  }

  private async handleMessage(msg: { type: string; [key: string]: unknown }): Promise<void> {
    switch (msg.type) {
      case "ready":
        this.view?.webview.postMessage({
          type: "state",
          state: this.store.toSerializable(),
        })
        break
      case "connect":
        await this.connection.connect()
        break
      case "disconnect":
        this.connection.disconnect()
        break
      case "selectSession":
        if (typeof msg.sessionId === "string") {
          await this.connection.selectSession(msg.sessionId)
        }
        break
      case "abortSession":
        if (typeof msg.sessionId === "string") {
          await this.connection.abortSession(msg.sessionId)
        }
        break
      case "openFile":
        if (typeof msg.path === "string") {
          const uri = vscode.Uri.file(msg.path)
          await vscode.window.showTextDocument(uri)
        }
        break
      case "openDiff":
        if (typeof msg.path === "string") {
          const uri = vscode.Uri.file(msg.path)
          await vscode.commands.executeCommand("vscode.diff", uri, uri, msg.path)
        }
        break
    }
  }

  private getHtml(webview: vscode.Webview): string {
    const scriptUri = webview.asWebviewUri(
      vscode.Uri.joinPath(this.extensionUri, "webview", "dist", "app.js")
    )
    const nonce = getNonce()

    return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src ${webview.cspSource} 'unsafe-inline'; script-src 'nonce-${nonce}';">
  <title>OpenCode Agent Observatory</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body {
      font-family: var(--vscode-font-family, system-ui, sans-serif);
      font-size: var(--vscode-font-size, 13px);
      color: var(--vscode-foreground, #cccccc);
      background: var(--vscode-editor-background, #1e1e1e);
      padding: 8px;
    }
    #root { width: 100%; }
  </style>
</head>
<body>
  <div id="root"></div>
  <script nonce="${nonce}" src="${scriptUri}"></script>
</body>
</html>`
  }

  dispose(): void {
    for (const d of this.disposables) d.dispose()
  }
}

function getNonce(): string {
  const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
  let result = ""
  for (let i = 0; i < 32; i++) {
    result += chars[Math.floor(Math.random() * chars.length)]
  }
  return result
}

