const api = acquireVsCodeApi()
let state: SerializableAgentState | null = null

window.addEventListener("message", (ev) => {
  const msg = ev.data
  if (msg.type === "state") {
    state = msg.state as SerializableAgentState
    render()
  }
})

api.postMessage({ type: "ready" })

function render(): void {
  const root = document.getElementById("root")
  if (!root || !state) return

  root.innerHTML = `
    ${renderHeader()}
    <div class="grid">
      <div class="col-main">
        ${renderTimeline()}
        ${renderDiff()}
      </div>
      <div class="col-side">
        ${renderCurrentAction()}
        ${renderFiles()}
        ${renderTodos()}
      </div>
    </div>
  `

