function renderHeader(): string {
  const conn = state!.connection
  const session = state!.activeSessionId
    ? state!.sessions[state!.activeSessionId]
    : undefined
  const statusClass =
    conn === "CONNECTED"
      ? session?.status === "RUNNING"
        ? "running"
        : "connected"
      : conn.toLowerCase()

  return `
    <div class="header">
      <div class="status ${statusClass}">
        <span class="dot"></span>
        <span>${conn}${session ? ` — ${session.title || session.id}` : ""}</span>
      </div>
      <div class="meta">
        ${state!.serverVersion ? `<span>v${state!.serverVersion}</span>` : ""}
        ${session?.model ? `<span>${session.model}</span>` : ""}
        <button class="btn" data-action="connect">Connect</button>
      </div>
    </div>
  `
}

function renderTimeline(): string {
  const events = state!.timeline.slice(-100)
  if (events.length === 0) {
    return `<div class="panel"><div class="panel-title">Timeline</div><div class="empty">No events yet</div></div>`
  }

  const items = events
    .map((ev) => {
      const time = new Date(ev.timestamp).toLocaleTimeString()
      const icon = eventIcon(ev.type)
      return `
        <div class="event ${ev.severity || ""}" data-file="${ev.filePath || ""}">
          <span class="time">${time}</span>
          <span class="icon">${icon}</span>
          <span class="title">${escapeHtml(ev.title)}</span>
          ${ev.filePath ? `<span class="file">${escapeHtml(ev.filePath)}</span>` : ""}
        </div>
      `
    })
    .join("")

  return `<div class="panel"><div class="panel-title">Timeline (${events.length})</div><div class="events">${items}</div></div>`
}

function renderCurrentAction(): string {
  const tool = state!.activeTool
  if (!tool) {
    return `<div class="panel"><div class="panel-title">Current Action</div><div class="empty">Idle</div></div>`
  }
  const elapsed = ((Date.now() - tool.startedAt) / 1000).toFixed(1)
  return `
    <div class="panel">
      <div class="panel-title">Current Action</div>
      <div class="current-action">
        <div class="tool-name">⚙ ${escapeHtml(tool.toolName)}</div>
        ${tool.filePath ? `<div class="tool-file">${escapeHtml(tool.filePath)}</div>` : ""}
        <div class="tool-elapsed">${elapsed}s</div>
      </div>
    </div>
  `
}

function renderFiles(): string {
  const files = Array.from(state!.files.values()).slice(-20)
  if (files.length === 0) {
    return `<div class="panel"><div class="panel-title">Files</div><div class="empty">No changes</div></div>`
  }

  const items = files
    .map((f) => {
      const icon = f.status === "added" ? "A" : f.status === "deleted" ? "D" : "M"
      return `<div class="file-item" data-file="${escapeHtml(f.path)}"><span class="badge ${f.status}">${icon}</span> ${escapeHtml(f.path)}</div>`
    })
    .join("")

  return `<div class="panel"><div class="panel-title">Files (${files.length})</div>${items}</div>`
}

function renderTodos(): string {
  const todos = state!.todos
  if (!todos || todos.length === 0) {
    return `<div class="panel"><div class="panel-title">TODO</div><div class="empty">No tasks</div></div>`
  }

  const items = todos
    .map((t) => {
      const icon =
        t.status === "completed"
          ? "✓"
          : t.status === "in_progress"
            ? "●"
            : t.status === "cancelled"
              ? "✗"
              : "○"
      return `<div class="todo-item ${t.status}"><span class="icon">${icon}</span> ${escapeHtml(t.content)}</div>`
    })
    .join("")

  return `<div class="panel"><div class="panel-title">TODO (${todos.length})</div>${items}</div>`
}

function renderDiff(): string {
  const diffs = Object.values(state!.diffs || {})
  if (diffs.length === 0) {
    return `<div class="panel"><div class="panel-title">Live Diff</div><div class="empty">No diff</div></div>`
  }

  const items = diffs
    .map((d) => `<div class="diff-file">${escapeHtml(d.filePath)} (+${d.totalAdded} -${d.totalRemoved})</div>`)
    .join("")

  return `<div class="panel"><div class="panel-title">Live Diff</div>${items}</div>`
}

function eventIcon(type: string): string {
  if (type.includes("TOOL_STARTED")) return "⚙"
  if (type.includes("TOOL_FINISHED")) return "✓"
  if (type.includes("TOOL_FAILED")) return "✗"
  if (type.includes("FILE")) return "✎"
  if (type.includes("SESSION")) return "●"
  if (type.includes("PERMISSION")) return "🔑"
  if (type.includes("TODO")) return "☐"
  return "○"
}

function escapeHtml(text: string): string {
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
}

function bindEvents(): void {
  document.querySelectorAll("[data-action='connect']").forEach((el) => {
    el.addEventListener("click", () => api.postMessage({ type: "connect" }))
  })
  document.querySelectorAll("[data-file]").forEach((el) => {
