import { describe, it, expect, vi, beforeEach } from "vitest"
import { normalizeEvent } from "../../src/events/EventNormalizer"

describe("EventNormalizer", () => {
  it("normalizes session.created event", () => {
    const event = normalizeEvent({
      type: "session.created",
      properties: {},
      sessionID: "abc123",
    })
    expect(event).not.toBeNull()
    expect(event!.type).toBe("SESSION_CREATED")
    expect(event!.sessionId).toBe("abc123")
    expect(event!.source).toBe("opencode")
    expect(event!.severity).toBe("success")
  })

  it("normalizes tool.execute.before event", () => {
    const event = normalizeEvent({
      type: "tool.execute.before",
      properties: { name: "read_file", path: "src/main.ts" },
    })
    expect(event).not.toBeNull()
    expect(event!.type).toBe("TOOL_STARTED")
    expect(event!.toolName).toBe("read_file")
    expect(event!.filePath).toBe("src/main.ts")
    expect(event!.title).toContain("read_file")
  })

  it("normalizes tool.execute.after event", () => {
    const event = normalizeEvent({
      type: "tool.execute.after",
      properties: { name: "edit_file", duration: 150 },
    })
    expect(event).not.toBeNull()
    expect(event!.type).toBe("TOOL_FINISHED")
    expect(event!.durationMs).toBe(150)
    expect(event!.severity).toBe("success")
  })

  it("normalizes file.edited event", () => {
    const event = normalizeEvent({
      type: "file.edited",
      properties: { path: "src/app.ts" },
    })
    expect(event).not.toBeNull()
    expect(event!.type).toBe("FILE_EDITED")
    expect(event!.filePath).toBe("src/app.ts")
  })

  it("normalizes session.error event", () => {
    const event = normalizeEvent({
      type: "session.error",
      properties: { message: "Connection timeout" },
    })
    expect(event).not.toBeNull()
    expect(event!.type).toBe("SESSION_ERROR")
    expect(event!.severity).toBe("error")
    expect(event!.detail).toBe("Connection timeout")
  })

  it("normalizes permission.asked event", () => {
    const event = normalizeEvent({
      type: "permission.asked",
      properties: { tool: "bash" },
    })
    expect(event).not.toBeNull()
    expect(event!.type).toBe("PERMISSION_REQUESTED")
    expect(event!.severity).toBe("warning")
  })

  it("returns null for unknown event types", () => {
    const event = normalizeEvent({ type: "unknown.event" })
    expect(event).toBeNull()
  })

  it("normalizes todo.updated event", () => {
    const event = normalizeEvent({
      type: "todo.updated",
      properties: { todos: [] },
    })
    expect(event).not.toBeNull()
    expect(event!.type).toBe("TODO_UPDATED")
  })
})

