import { describe, it, expect, vi, beforeEach } from "vitest"
import { StateStore } from "../../src/state/StateStore"
import type { SessionState, ToolExecution, TodoItem } from "../../src/events/EventTypes"

function makeSession(id: string, overrides?: Partial<SessionState>): SessionState {
  return {
    id,
    title: `Session ${id}`,
    model: "claude-opus-4-7",
    status: "IDLE",
    startedAt: Date.now(),
    lastActivityAt: Date.now(),
    messages: 0,
    ...overrides,
  }
}

describe("StateStore", () => {
  let store: StateStore

  beforeEach(() => {
    store = new StateStore()
  })

  it("initializes with disconnected state", () => {
    expect(store.getState().connection).toBe("DISCONNECTED")
    expect(store.getState().sessions.size).toBe(0)
    expect(store.getState().timeline.length).toBe(0)
  })

  it("updates connection state", () => {
    store.setConnection("CONNECTED")
    expect(store.getState().connection).toBe("CONNECTED")
  })

  it("sets and gets sessions", () => {
    const sessions = [makeSession("1"), makeSession("2")]
    store.setSessions(sessions)
    expect(store.getState().sessions.size).toBe(2)
    expect(store.getState().sessions.get("1")?.title).toBe("Session 1")
  })

  it("sets active session", () => {
    store.setSessions([makeSession("a"), makeSession("b")])
    store.setActiveSession("b")
    expect(store.getState().activeSessionId).toBe("b")
  })

  it("adds events to timeline", () => {
    const event = {
      id: "evt_1",
      timestamp: Date.now(),
      type: "TOOL_STARTED" as const,
      source: "opencode" as const,
      title: "Reading file",
    }
    store.addEvent(event)
    expect(store.getState().timeline.length).toBe(1)
    expect(store.getState().timeline[0].title).toBe("Reading file")
  })

  it("caps timeline at MAX_TIMELINE", () => {
    for (let i = 0; i < 5100; i++) {
      store.addEvent({
        id: `evt_${i}`,
        timestamp: Date.now() + i,
        type: "TOOL_STARTED",
        source: "opencode",
        title: `Event ${i}`,
      })
    }
    expect(store.getState().timeline.length).toBe(5000)
  })

  it("manages tool lifecycle", () => {
    const tool: ToolExecution = {
      id: "t1",
      sessionId: "s1",
      toolName: "read_file",
      startedAt: Date.now(),
      status: "running",
    }
    store.setToolRunning(tool)
    expect(store.getState().activeTool?.toolName).toBe("read_file")

    store.setToolFinished("t1", "success")
    expect(store.getState().activeTool).toBeUndefined()
    expect(store.getState().recentTools.length).toBe(1)
    expect(store.getState().recentTools[0].status).toBe("success")
  })

  it("manages file state", () => {
    store.setFile({ path: "src/app.ts", status: "modified", changedAt: Date.now() })
    expect(store.getState().files.has("src/app.ts")).toBe(true)
  })

  it("manages todos", () => {
    const todos: TodoItem[] = [
      { id: "1", content: "Task 1", status: "completed" },
      { id: "2", content: "Task 2", status: "pending" },
    ]
    store.setTodos(todos)
    expect(store.getState().todos.length).toBe(2)
  })

  it("manages permissions", () => {
    store.addPermission({
      id: "p1",
      sessionId: "s1",
      toolName: "bash",
      description: "Execute command",
      requestedAt: Date.now(),
    })
    expect(store.getState().permissions.length).toBe(1)

    store.resolvePermission("p1", "allow")
    expect(store.getState().permissions[0].resolved).toBe(true)
    expect(store.getState().permissions[0].response).toBe("allow")
  })

  it("serializes state for webview", () => {
    store.setConnection("CONNECTED")
    store.setServerVersion("1.0.0")
    const serialized = store.toSerializable()
    expect(serialized.connection).toBe("CONNECTED")
    expect(serialized.serverVersion).toBe("1.0.0")
  })
})

