export class OpenCodeConnection {
  private client: OpencodeClient | null = null
  private eventSource: EventSource | null = null
  private store: StateStore
  private outputChannel: vscode.OutputChannel
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null
  private reconnectDelay = 1000
  private maxReconnectDelay = 30000
  private disposed = false
  private config: () => { url: string; autoConnect: boolean; debug: boolean }

  constructor(
    store: StateStore,
    outputChannel: vscode.OutputChannel,
    config: () => { url: string; autoConnect: boolean; debug: boolean }
  ) {
    this.store = store
    this.outputChannel = outputChannel
    this.config = config
  }

  get isConnected(): boolean {
    return this.store.getState().connection === "CONNECTED"
  }

  async connect(): Promise<void> {
    if (this.disposed) return
    const { url, debug } = this.config()

    this.store.setConnection("CONNECTING")
    this.log(debug, `Connecting to ${url}...`)

    try {
      this.client = createOpencodeClient({ baseUrl: url })

      const health = await this.client.global.health()
      if (!health.data?.healthy) {
        throw new Error("Server unhealthy")
      }

      this.store.setServerVersion(health.data.version || "unknown")
      this.store.setConnection("CONNECTED")
      this.reconnectDelay = 1000
      this.log(debug, `Connected — v${health.data.version}`)

      await this.loadSessions()
      this.startSSE()
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err)
      this.store.setConnection("ERROR")
      this.store.setError(msg)
      this.log(debug, `Connection failed: ${redactSecrets(msg)}`)
      this.scheduleReconnect()
    }
  }

  disconnect(): void {
    this.disposed = true
    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer)
      this.reconnectTimer = null
    }
    this.stopSSE()
    this.store.setConnection("DISCONNECTED")
    this.store.setError(undefined)
  }

  async reconnect(): Promise<void> {
    this.disposed = false
    this.stopSSE()
    await this.connect()
  }

  private scheduleReconnect(): void {
    if (this.disposed) return
    const { debug } = this.config()

    this.reconnectTimer = setTimeout(async () => {
      if (this.disposed) return
      this.log(debug, `Reconnecting (delay ${this.reconnectDelay}ms)...`)
      this.store.setConnection("RECONNECTING")
      await this.connect()
    }, this.reconnectDelay)

    this.reconnectDelay = Math.min(this.reconnectDelay * 2, this.maxReconnectDelay)
  }

  private async loadSessions(): Promise<void> {
    if (!this.client) return
    try {
      const res = await this.client.session.list()
      const sessions: SessionState[] = (res.data || []).map((s: any) => ({
        id: s.id,
        title: s.title || s.id,
        model: s.modelID || s.model,
        status: s.status || "IDLE",
        startedAt: s.createdAt ? new Date(s.createdAt).getTime() : Date.now(),
        lastActivityAt: s.updatedAt ? new Date(s.updatedAt).getTime() : Date.now(),
        messages: s.messages || 0,
      }))
      this.store.setSessions(sessions)
    } catch (err) {
      this.log(this.config().debug, `Failed to load sessions: ${err}`)
    }
  }

  private startSSE(): void {
    if (!this.client) return
    const { debug } = this.config()

    const url = `${this.config().url}/event`
    this.eventSource = new EventSource(url)

    this.eventSource.onmessage = (ev) => {
      try {
        const raw = JSON.parse(ev.data)
        const normalized = normalizeEvent(raw, this.store.getState().activeSessionId)
        if (normalized) {
          this.store.addEvent(normalized)
          this.handleEvent(normalized)
          if (debug) {
            this.outputChannel.appendLine(`[SSE] ${normalized.type}: ${normalized.title}`)
          }
        }
      } catch {
        // parse error — skip
      }
    }

    this.eventSource.onerror = () => {
      this.log(debug, "SSE connection lost")
      this.stopSSE()
      this.scheduleReconnect()
    }
  }

  private stopSSE(): void {
    if (this.eventSource) {
      this.eventSource.close()
      this.eventSource = null
    }
  }

  private handleEvent(event: ReturnType<typeof normalizeEvent> & Record<string, unknown>): void {
    if (!event) return
    const props = (event.payload as Record<string, unknown>) || {}

    switch (event.type) {
      case "TOOL_STARTED": {
        const tool: ToolExecution = {
          id: event.id,
          sessionId: event.sessionId || "",
          toolName: event.toolName || "unknown",
          startedAt: event.timestamp,
          status: "running",
          filePath: event.filePath,
        }
        this.store.setToolRunning(tool)
        break
      }
      case "TOOL_FINISHED":
      case "TOOL_FAILED":
        this.store.setToolFinished(event.id, event.type === "TOOL_FAILED" ? "error" : "success")
        break
      case "FILE_EDITED":
      case "FILE_CHANGED":
        if (event.filePath) {
          this.store.setFile({
            path: event.filePath,
            status: "modified",
            changedAt: event.timestamp,
          })
        }
        break
      case "TODO_UPDATED":
        if (Array.isArray(props.todos)) {
          this.store.setTodos(props.todos as TodoItem[])
        }
        break
      case "PERMISSION_REQUESTED": {
        const req: PermissionRequest = {
          id: event.id,
          sessionId: event.sessionId || "",
          toolName: event.toolName || "unknown",
          description: event.detail || "Permission required",
          input: props.input,
          requestedAt: event.timestamp,
        }
        this.store.addPermission(req)
        break
      }
      case "SESSION_CREATED":
      case "SESSION_UPDATED":
      case "SESSION_IDLE":
      case "SESSION_ERROR":
        this.loadSessions()
        break
    }
  }

  async abortSession(sessionId: string): Promise<void> {
    if (!this.client) return
    try {
      await this.client.session.abort({ path: { id: sessionId } })
      this.log(this.config().debug, `Aborted session ${sessionId}`)
    } catch (err) {
      this.log(this.config().debug, `Abort failed: ${err}`)
    }
  }

  async selectSession(sessionId: string): Promise<void> {
    this.store.setActiveSession(sessionId)
  }

  private log(debug: boolean, msg: string): void {
