import * as vscode from "vscode"
import { StateStore } from "./state/StateStore"
import { OpenCodeConnection } from "./opencode/OpenCodeConnection"
import { ObservatoryViewProvider } from "./providers/ObservatoryViewProvider"
import { StatusBarProvider } from "./providers/StatusBarProvider"
import { registerCommands } from "./commands/registerCommands"

let connection: OpenCodeConnection | undefined
let statusBar: StatusBarProvider | undefined

export function activate(context: vscode.ExtensionContext): void {
  const outputChannel = vscode.window.createOutputChannel("OpenCode Agent Observatory")
  context.subscriptions.push(outputChannel)

  const store = new StateStore(outputChannel)

  const getConfig = () => {
    const cfg = vscode.workspace.getConfiguration("opencodeObservatory")
    return {
      url: cfg.get<string>("server.url", "http://127.0.0.1:4096"),
      autoConnect: cfg.get<boolean>("autoConnect", true),
      autoStartServer: cfg.get<boolean>("autoStartServer", false),
      debug: cfg.get<boolean>("debug", false),
    }
  }

  connection = new OpenCodeConnection(store, outputChannel, getConfig)

  const provider = new ObservatoryViewProvider(context.extensionUri, store, connection)
  context.subscriptions.push(
    vscode.window.registerWebviewViewProvider("opencodeObservatory.main", provider, {
      webviewOptions: { retainContextWhenHidden: true },
    })
  )

  statusBar = new StatusBarProvider(store)
  context.subscriptions.push(statusBar)

  registerCommands(context, store, connection)

  if (getConfig().autoConnect) {
    connection.connect()
  }
}

export function deactivate(): void {
  connection?.dispose()
  statusBar?.dispose()
}

