async connect(): Promise<void> {
  if (this.disposed) return
  this.store.setConnection("CONNECTING")
  this.log(`Connecting to ${this.url}...`)

  try {
    const sdk = await import("@opencode-ai/sdk")
    const createClient = (sdk as any).createOpencodeClient || (sdk as any).default?.createOpencodeClient
    if (!createClient) throw new Error("SDK createOpencodeClient not found")
    this.client = createClient({ baseUrl: this.url }) as OpencodeClient

    const health = await this.client.global.health()
    if (!health.data?.healthy) throw new Error("Server unhealthy")

    this.store.setServerVersion(health.data.version || "unknown")
    this.store.setConnection("CONNECTED")
    this.reconnectDelay = 1000
    this.log(`Connected — v${health.data.version}`)

    await this.loadSessions()
    this.startSSE()
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err)
    this.log(`Connection failed: ${redactSecrets(msg)}`)
    if (this.store.getState().connection !== "CONNECTED") {
      this.store.setConnection("RECONNECTING" as any)
    }
    this.scheduleReconnect()
  }
}

