import type { NormalizedAgentEvent } from "./EventTypes"

type FlushCallback = (events: NormalizedAgentEvent[]) => void

const BATCH_INTERVAL_MS = 30
const MAX_BATCH_SIZE = 100
const COALESCE_WINDOW_MS = 50

interface BatchEntry {
  event: NormalizedAgentEvent
  receivedAt: number
}

export class EventBatcher {
  private buffer: BatchEntry[] = []
  private timer: ReturnType<typeof setTimeout> | null = null
  private onFlush: FlushCallback
  private eventCount = 0
  private droppedCount = 0

  constructor(onFlush: FlushCallback) {
    this.onFlush = onFlush
  }

  push(event: NormalizedAgentEvent): void {
    this.eventCount++

    if (this.buffer.length >= MAX_BATCH_SIZE) {
      this.droppedCount++
      return
    }

    const last = this.buffer[this.buffer.length - 1]
    if (last && this.canCoalesce(last.event, event)) {
      last.event = event
      last.receivedAt = Date.now()
      return
    }

    this.buffer.push({ event, receivedAt: Date.now() })

    if (!this.timer) {
      this.timer = setTimeout(() => this.flush(), BATCH_INTERVAL_MS)
    }
  }

  private canCoalesce(a: NormalizedAgentEvent, b: NormalizedAgentEvent): boolean {
    if (a.type !== b.type) return false
    if (a.sessionId !== b.sessionId) return false
    const delta = Math.abs(a.timestamp - b.timestamp)
    return delta < COALESCE_WINDOW_MS
  }

  flush(): void {
    if (this.timer) {
      clearTimeout(this.timer)
      this.timer = null
    }
    if (this.buffer.length === 0) return
    const batch = this.buffer.splice(0, this.buffer.length)
    this.onFlush(batch.map((e) => e.event))
  }

  getMetrics(): { received: number; dropped: number; buffered: number } {
    return {
      received: this.eventCount,
      dropped: this.droppedCount,
      buffered: this.buffer.length,
    }
  }

  dispose(): void {
    if (this.timer) {
      clearTimeout(this.timer)
      this.timer = null
    }
    this.buffer = []
  }
}

