cleanup(maxAgeMs: number = 300_000): void {
  const cutoff = Date.now() - maxAgeMs
  for (const [path, file] of this.state.files) {
    if (file.changedAt < cutoff) this.state.files.delete(path)
  }
  for (const [path, diff] of this.state.diffs) {
    if (diff.updatedAt < cutoff) this.state.diffs.delete(path)
  }
  this.state.permissions = this.state.permissions.filter(
    (p) => p.requestedAt > cutoff || !p.resolved
  )
}

