export class OpenCodeConnection {
  private client: OpencodeClient | null = null
  private eventSource: any = null
  private store: StateStore
  private logFn: (msg: string) => void
  private batcher: EventBatcher
  private reconnectTimer: any = null
  private reconnectDelay = 1000
  private maxReconnectDelay = 30000
  private disposed = false
  private url: string
  private debug: boolean

  constructor(
    store: StateStore,
    logFn: (msg: string) => void,
    getConfig: () => { url: string; debug: boolean }
  ) {
    this.store = store
    this.logFn = logFn
    const cfg = getConfig()
    this.url = cfg.url
    this.debug = cfg.debug
    this.batcher = new EventBatcher((events) => {
      this.store.addEventsBatch(events)
      for (const ev of events) this.handleEvent(ev)
    })
  }

export class OpenCodeConnection {
  private client: OpencodeClient | null = null
  private eventSource: any = null
  private store: StateStore
  private logFn: (msg: string) => void
  private batcher: EventBatcher
  private reconnectTimer: any = null
  private reconnectDelay = 1000
  private maxReconnectDelay = 30000
  private disposed = false
  private url: string
  private debug: boolean

  constructor(
    store: StateStore,
    logFn: (msg: string) => void,
    getConfig: () => { url: string; debug: boolean }
  ) {
    this.store = store
    this.logFn = logFn
    const cfg = getConfig()
    this.url = cfg.url
    this.debug = cfg.debug
    this.batcher = new EventBatcher((events) => {
      this.store.addEventsBatch(events)
      for (const ev of events) this.handleEvent(ev)
    })
  }

this.eventSource.onmessage = (ev: any) => {
  try {
    const raw = JSON.parse(ev.data)
    const normalized = normalizeEvent(raw, this.store.getState().activeSessionId)
    if (normalized) {
      this.batcher.push(normalized)
      if (this.debug) this.log(`[SSE] ${normalized.type}: ${normalized.title}`)
    }
  } catch { /* parse error */ }
}

