const SECRET_PATTERNS: RegExp[] = [
  /(?:api[_-]?key|apikey)\s*[=:]\s*['"]?([^\s'"<>]{8,})/gi,
  /(?:bearer|token)\s+[A-Za-z0-9\-._~+/]+=*/gi,
  /(?:password|passwd|pwd)\s*[=:]\s*['"]?([^\s'"<>]{4,})/gi,
  /(?:secret|secret_key)\s*[=:]\s*['"]?([^\s'"<>]{8,})/gi,
  /(?:private[_-]?key)\s*[=:]\s*['"]?([^\s'"<>]{8,})/gi,
  /(?:sk-[a-zA-Z0-9]{20,})/g,
  /(?:ghp_[a-zA-Z0-9]{36})/g,
  /(?:xoxb-[a-zA-Z0-9\-]+)/g,
]

const KEY_PATTERN = /key|secret|token|password|credential/i
const REDACTED = "[REDACTED]"

let redactCache = new Map<string, string>()
const CACHE_MAX = 500

export function redactSecrets(text: string): string {
  if (text.length > 10000) return text
  const cached = redactCache.get(text)
  if (cached !== undefined) return cached
  let result = text
  for (const pattern of SECRET_PATTERNS) {
    pattern.lastIndex = 0
    result = result.replace(pattern, REDACTED)
  }
  if (redactCache.size > CACHE_MAX) redactCache.clear()
  redactCache.set(text, result)
  return result
}

export function redactObject(obj: unknown): unknown {
  if (typeof obj === "string") return redactSecrets(obj)
  if (Array.isArray(obj)) return obj.map(redactObject)
  if (obj && typeof obj === "object") {
    const result: Record<string, unknown> = {}
    for (const [key, value] of Object.entries(obj)) {
      if (KEY_PATTERN.test(key) && typeof value === "string") {
        result[key] = REDACTED
      } else {
        result[key] = redactObject(value)
      }
    }
    return result
  }
  return obj
}

export function clearRedactCache(): void {
  redactCache.clear()
}

const SECRET_PATTERNS: RegExp[] = [
  /(?:api[_-]?key|apikey)\s*[=:]\s*['"]?([^\s'"<>]{8,})/gi,
  /(?:bearer|token)\s+[A-Za-z0-9\-._~+/]+=*/gi,
  /(?:password|passwd|pwd)\s*[=:]\s*['"]?([^\s'"<>]{4,})/gi,
  /(?:secret|secret_key)\s*[=:]\s*['"]?([^\s'"<>]{8,})/gi,
  /(?:private[_-]?key)\s*[=:]\s*['"]?([^\s'"<>]{8,})/gi,
  /(?:sk-[a-zA-Z0-9]{20,})/g,
  /(?:ghp_[a-zA-Z0-9]{36})/g,
  /(?:xoxb-[a-zA-Z0-9\-]+)/g,
]

const KEY_PATTERN = /key|secret|token|password|credential/i
const REDACTED = "[REDACTED]"

let redactCache = new Map<string, string>()
const CACHE_MAX = 500

export function redactSecrets(text: string): string {
  if (text.length > 10000) return text
  const cached = redactCache.get(text)
  if (cached !== undefined) return cached
  let result = text
  for (const pattern of SECRET_PATTERNS) {
    pattern.lastIndex = 0
    result = result.replace(pattern, REDACTED)
  }
  if (redactCache.size > CACHE_MAX) redactCache.clear()
  redactCache.set(text, result)
  return result
}

export function redactObject(obj: unknown): unknown {
  if (typeof obj === "string") return redactSecrets(obj)
  if (Array.isArray(obj)) return obj.map(redactObject)
  if (obj && typeof obj === "object") {
    const result: Record<string, unknown> = {}
    for (const [key, value] of Object.entries(obj)) {
      if (KEY_PATTERN.test(key) && typeof value === "string") {
        result[key] = REDACTED
      } else {
        result[key] = redactObject(value)
      }
    }
    return result
  }
  return obj
}

export function clearRedactCache(): void {
  redactCache.clear()
}

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest"
import { EventBatcher } from "../../src/events/EventBatcher"
import type { NormalizedAgentEvent } from "../../src/events/EventTypes"

function makeEvent(type: string, overrides?: Partial<NormalizedAgentEvent>): NormalizedAgentEvent {
  return {
    id: `evt_${Date.now()}_${Math.random()}`,
    timestamp: Date.now(),
    type: type as any,
    source: "opencode",
    title: type,
    ...overrides,
  }
}

describe("EventBatcher", () => {
  afterEach(() => {
    vi.restoreAllMocks()
  })

  it("batches multiple events into a single flush", () => {
    const flush = vi.fn()
    const batcher = new EventBatcher(flush)

    batcher.push(makeEvent("TOOL_STARTED"))
    batcher.push(makeEvent("TOOL_FINISHED"))
    batcher.push(makeEvent("FILE_EDITED"))

    batcher.flush()
    expect(flush).toHaveBeenCalledTimes(1)
    expect(flush).toHaveBeenCalledWith(expect.arrayContaining([
      expect.objectContaining({ type: "TOOL_STARTED" }),
      expect.objectContaining({ type: "TOOL_FINISHED" }),
      expect.objectContaining({ type: "FILE_EDITED" }),
    ]))
  })

  it("coalesces rapid events of the same type", () => {
    const flush = vi.fn()
    const batcher = new EventBatcher(flush)

    const now = Date.now()
    batcher.push(makeEvent("MESSAGE_PART_UPDATED", { timestamp: now }))
    batcher.push(makeEvent("MESSAGE_PART_UPDATED", { timestamp: now + 10 }))
    batcher.push(makeEvent("MESSAGE_PART_UPDATED", { timestamp: now + 20 }))

    batcher.flush()
    expect(flush).toHaveBeenCalledTimes(1)
    expect(flush).toHaveBeenCalledWith(expect.arrayContaining([
      expect.objectContaining({ type: "MESSAGE_PART_UPDATED" }),
    ]))
    expect(flush.mock.calls[0][0]).toHaveLength(1)
  })

  it("does not coalesce events of different types", () => {
    const flush = vi.fn()
    const batcher = new EventBatcher(flush)

    batcher.push(makeEvent("TOOL_STARTED"))
    batcher.push(makeEvent("FILE_EDITED"))

    batcher.flush()
    expect(flush).toHaveBeenCalledWith(expect.arrayContaining([
      expect.objectContaining({ type: "TOOL_STARTED" }),
      expect.objectContaining({ type: "FILE_EDITED" }),
    ]))
    expect(flush.mock.calls[0][0]).toHaveLength(2)
  })

  it("drops events when buffer is full", () => {
    const flush = vi.fn()
    const batcher = new EventBatcher(flush)

    for (let i = 0; i < 150; i++) {
      batcher.push(makeEvent("TOOL_STARTED", { timestamp: Date.now() + i * 100 }))
    }

    const metrics = batcher.getMetrics()
    expect(metrics.buffered).toBeLessThanOrEqual(100)
    expect(metrics.dropped).toBeGreaterThan(0)
  })

  it("tracks metrics correctly", () => {
    const batcher = new EventBatcher(() => {})

    batcher.push(makeEvent("TOOL_STARTED"))
    batcher.push(makeEvent("FILE_EDITED"))

    const metrics = batcher.getMetrics()
    expect(metrics.received).toBe(2)
    expect(metrics.dropped).toBe(0)
    expect(metrics.buffered).toBe(2)
  })

  it("dispose clears buffer", () => {
    const batcher = new EventBatcher(() => {})
    batcher.push(makeEvent("TOOL_STARTED"))
    batcher.dispose()
    expect(batcher.getMetrics().buffered).toBe(0)
  })
})

